package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPointTaskPoliciesTest extends JdbcCouponInventoryTest {
 PointTaskPolicies policies;
 @BeforeEach void points(){jdbc.execute("DROP TRIGGER IF EXISTS fail_points_audit");jdbc.update("DELETE FROM point_task_policy");jdbc.update("UPDATE operator_account SET can_points=1 WHERE id=1");policies=new PointTaskPolicies(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));}
 ObjectNode task(String kind){return json.createObjectNode().put("task_type",kind).put("points",7).put("source_note","用户确认的合成测试规则").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(3600).toString());}
 long draftTask(String kind){var b=task(kind);PointTaskPolicies.input(b.toString(),false);return policies.create(operator,key(),b).path("data").path("id").asLong();}
 void activateTask(long id){policies.status(operator,id,key(),statusBody(1,"PUBLISHED"));}
 @Test void noConfigurationIsUnknownAndPublicationNeverAwardsLegacyOrTestPoints(){var initial=policies.current(owner);assertEquals(false,initial.get("earning_available"));assertEquals(3,((List<?>)initial.get("tasks")).size());assertFalse(db.json(initial).contains("CONFIGURED"));jdbc.update("UPDATE user SET point_balance=999 WHERE id=1");long id=draftTask("CHECK_IN");activateTask(id);String view=db.json(policies.current(owner));assertTrue(view.contains("CONFIGURED"));assertTrue(view.contains("DAILY"));assertEquals(999,jdbc.queryForObject("SELECT point_balance FROM user WHERE id=1",Integer.class));assertEquals(0,count("point_flow"));assertEquals(0,count("point_exchange"));assertEquals(0,count("coupon_issue"));}
 @Test void privilegeIsSeparateAndCachedWritesReauthorize(){jdbc.update("UPDATE operator_account SET can_points=0,can_invite=1,can_coupon=1,can_diagnose_manage=1 WHERE id=1");assertEquals(403,code(()->policies.list(operator,1)));assertEquals(403,code(()->policies.create(operator,key(),task("CHECK_IN"))));jdbc.update("UPDATE operator_account SET can_points=1 WHERE id=1");String key=key();var b=task("CHECK_IN");policies.create(operator,key,b);jdbc.update("UPDATE operator_account SET can_points=0 WHERE id=1");assertEquals(403,code(()->policies.create(operator,key,b)));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->policies.current(owner)));}
 @Test void publishedTasksAreIndependentAndExactlyOneVersionPerTask(){for(String kind:PointTaskPolicies.TASKS)activateTask(draftTask(kind));assertEquals(3,count("point_task_policy"));long duplicate=draftTask("CHECK_IN");assertEquals(409,code(()->activateTask(duplicate)));assertEquals(3,jdbc.queryForObject("SELECT COUNT(*) FROM point_task_policy WHERE status='PUBLISHED'",Integer.class));var items=(List<?>)policies.current(owner).get("tasks");assertTrue(db.json(items.get(1)).contains("LIFETIME"));assertFalse(db.json(policies.list(operator,1)).contains("submission_hash"));assertFalse(db.json(policies.current(owner)).contains("creation_result"));}
 @Test void draftCasPublishFreezeStopAndValidityAreExplicit(){long id=draftTask("AI_FIRST_SUCCESS");var edit=task("AI_FIRST_SUCCESS").put("expected_revision",1).put("points",9);policies.update(operator,id,key(),edit);assertEquals(409,code(()->policies.update(operator,id,key(),edit)));policies.status(operator,id,key(),statusBody(2,"PUBLISHED"));assertEquals(409,code(()->policies.update(operator,id,key(),edit.put("expected_revision",3))));clock.value=clock.value.plusSeconds(3600);assertTrue(db.json(policies.current(owner)).contains("EXPIRED"));policies.status(operator,id,key(),statusBody(3,"STOPPED"));assertFalse(db.json(policies.current(owner)).contains("EXPIRED"));assertEquals(409,code(()->policies.status(operator,id,key(),statusBody(4,"PUBLISHED"))));}
 @Test void futurePolicyCannotPretendToBeUsableAndEndBoundaryIsExclusive(){var b=task("ARCHIVE_FIRST_COMPLETE").put("valid_from",clock.value.plusSeconds(600).toString());long id=policies.create(operator,key(),b).path("data").path("id").asLong();activateTask(id);assertTrue(db.json(policies.current(owner)).contains("NOT_STARTED"));clock.value=clock.value.plusSeconds(600);assertTrue(db.json(policies.current(owner)).contains("CONFIGURED"));clock.value=clock.value.plusSeconds(3000);assertTrue(db.json(policies.current(owner)).contains("EXPIRED"));}
 @Test void permanentCreationIntentSurvivesGenericReceiptExpiryAndPolicyChanges(){String key=key();var b=task("CHECK_IN");var first=policies.create(operator,key,b);long id=first.path("data").path("id").asLong();activateTask(id);jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");var replay=policies.create(operator,key,b);assertEquals(first.path("data"),replay.path("data"));assertEquals(1,count("point_task_policy"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='POINT_POLICY_CREATE'",Integer.class));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(400,code(()->policies.create(operator,key,task("CHECK_IN").put("points",8))));}
 @Test void auditFailureRollsBackIntentAndBusinessWrites(){jdbc.execute("CREATE TRIGGER fail_points_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");String key=key();assertEquals(503,code(()->policies.create(operator,key,task("CHECK_IN"))));assertEquals(0,count("point_task_policy"));jdbc.execute("DROP TRIGGER fail_points_audit");long id=policies.create(operator,key,task("CHECK_IN")).path("data").path("id").asLong();jdbc.execute("CREATE TRIGGER fail_points_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->activateTask(id)));assertEquals("DRAFT",jdbc.queryForObject("SELECT status FROM point_task_policy WHERE id=?",String.class,id));}
 @Test void concurrentOperatorsCannotPublishTwoVersions()throws Exception{long first=draftTask("CHECK_IN"),second=draftTask("CHECK_IN");jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_points) VALUES(2,'point-peer','unused','13800000001',1)");var peerOp=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),java.time.Instant.now().plusSeconds(600));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();try{activateTask(first);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var b=pool.submit(()->{start.await();try{policies.status(peerOp,second,key(),statusBody(1,"PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertEquals(List.of(200,409),result);}finally{pool.shutdownNow();}}
 @Test void strictInputRejectsForgedFrequencyFractionalOrMissingPoints(){for(String raw:List.of(task("CHECK_IN").put("frequency","LIFETIME").toString(),task("OTHER").toString(),task("CHECK_IN").put("points",0).toString(),task("CHECK_IN").put("points",1.5).toString(),task("CHECK_IN").put("points",1000001).toString(),task("CHECK_IN").put("source_note"," x ").toString(),task("CHECK_IN").put("valid_to",clock.value.toString()).toString(),task("CHECK_IN")+"{}"))assertThrows(Exception.class,()->PointTaskPolicies.input(raw,false));assertThrows(Exception.class,()->policies.list(operator,0));}
}
